import { DropdownMenuNested, MenuEntry } from "@/components/design-for-ai/dropdown-menu-nested";
import { Copy, Tag, Trash2 } from "lucide-react";

const items: MenuEntry[] = [
  { kind: "action", id: "duplicate", label: "Duplicate", icon: Copy, shortcut: "⌘D" },
  {
    kind: "submenu", id: "labels", label: "Labels", icon: Tag,
    items: [
      { kind: "checkbox", id: "urgent", label: "Urgent" },
      { kind: "checkbox", id: "legal", label: "Legal hold", defaultChecked: true },
    ],
  },
  { kind: "separator", id: "sep" },
  { kind: "action", id: "delete", label: "Delete brief", icon: Trash2, destructive: true, description: "Removes it for everyone" },
];

<DropdownMenuNested
  triggerLabel="Q4 launch brief"
  items={items}
  onSelect={(id) => run(id)}
  onCheckedChange={(id, on) => setLabel(id, on)}
/>

// The menu and its submenus position inside the component (no portal). To escape a
// clipping parent, render the component inside a fixed layer on document.body.
